export default async function FlashEventDetailPage({ params, searchParams }: Props) {
  const { id } = await params
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  try {
    await requireFeatureRpc(supabase, auth.studioId, 'flash_events')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      redirect('/settings/billing?upsell=flash_events')
    }
    throw err
  }

  // Derive sub-feature flags from plan tier (static — no extra DB round-trip)
  const planTier = auth.studio?.plan_tier ?? 'solo'
  const hasAnalytics = hasFeature(planTier, 'analytics')
  const hasSmsReminders = hasFeature(planTier, 'sms_reminders')

  const resolvedSearch = await searchParams
  const tab = typeof resolvedSearch.tab === 'string' ? resolvedSearch.tab : 'overview'

  const [event, slots, styleTags] = await Promise.all([
    getFlashEvent(auth.studioId, id),
    getFlashEventSlots(auth.studioId, id).catch(() => []),
    listStyleTags(auth.studioId).catch(() => []),
  ])

  if (!event) notFound()

  // Revenue panel is analytics-gated — skip the query entirely when plan doesn't have it
  const revenueBreakdown = hasAnalytics
    ? await getFlashEventRevenueBreakdown(auth.studioId, id).catch(() => null)
    : null

  return (
    <FlashEventDetailShell
      event={event}
      slots={slots}
      role={auth.role as NavRole}
      initialTab={tab}
      studioId={auth.studioId}
      styleTags={styleTags}
      revenueBreakdown={revenueBreakdown}
      hasAnalytics={hasAnalytics}
      hasSmsReminders={hasSmsReminders}
    />
  )

